

const [form, setForm] = useState({
    name: "",
    email: "",
    phone: "",
    purpose: "",
    date: "",
    time: "",
    message: "",
  });

  const handleChange = (e) => {
    setForm({ ...form, [e.target.name]: e.target.value });
  };

  const handleSubmit = (e) => {
    e.preventDefault();
    console.log("Form submitted:", form);
    // TODO: send data to API or email
  };

  return (
    <div className="min-h-screen bg-gradient-to-r from-purple-500 to-pink-500 flex items-center justify-center p-6">
      <div className="bg-white shadow-xl rounded-2xl w-full max-w-5xl grid md:grid-cols-2">
        
        {/* Left Side - Info */}
        <div className="p-10 flex flex-col justify-center text-white bg-gradient-to-b from-purple-600 to-pink-600 rounded-l-2xl">
          <h1 className="text-3xl font-bold mb-4">Book an Appointment Now</h1>
          <p className="mb-6">Let&apos;s Chat And Know More About You</p>
          <p className="mt-auto font-semibold">Contact Us Now!!</p>
        </div>

        {/* Right Side - Form */}
        <div className="p-10">
          <h2 className="text-2xl font-bold mb-6">Appointment</h2>
          <form onSubmit={handleSubmit} className="space-y-4">
            
            <input
              type="text"
              name="name"
              placeholder="Name *"
              value={form.name}
              onChange={handleChange}
              className="input input-bordered w-full"
              required
            />

            <input
              type="email"
              name="email"
              placeholder="Email *"
              value={form.email}
              onChange={handleChange}
              className="input input-bordered w-full"
              required
            />

            <input
              type="tel"
              name="phone"
              placeholder="Phone"
              value={form.phone}
              onChange={handleChange}
              className="input input-bordered w-full"
            />

            <select
              name="purpose"
              value={form.purpose}
              onChange={handleChange}
              className="select select-bordered w-full"
            >
              <option disabled value="">
                Select Purpose
              </option>
              <option>Consultation</option>
              <option>Support</option>
              <option>Business Inquiry</option>
            </select>

            <input
              type="date"
              name="date"
              value={form.date}
              onChange={handleChange}
              className="input input-bordered w-full"
            />

            <input
              type="time"
              name="time"
              value={form.time}
              onChange={handleChange}
              className="input input-bordered w-full"
            />

            <textarea
              name="message"
              placeholder="Message"
              value={form.message}
              onChange={handleChange}
              className="textarea textarea-bordered w-full"
              rows="4"
            ></textarea>

            <button type="submit" className="btn btn-primary w-full">
              SUBMIT
            </button>
          </form>
        </div>
      </div>
    </div>
  );